package com.chatApp.cloudChat.service;
import com.chatApp.cloudChat.model.*;
import com.chatApp.cloudChat.repository.*;
import com.chatApp.cloudChat.event.ContactEvent;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.security.access.AccessDeniedException;
import tools.jackson.databind.ObjectMapper;
import java.util.*;
import java.time.Instant;
import jakarta.persistence.EntityManager;
import jakarta.persistence.LockModeType;

@Service
@Transactional
public class NebulaService {
 private final MessagesRepo messages;
 private final NebulaRepo repo; private final ConversationRepo rooms; private final ConversationMemberRepo members;
 private final UsersRepo users; private final ObjectMapper json; private final ApplicationEventPublisher events; private final EntityManager em;
 private static final Set<String> COLORS=Set.of("#3B82F6","#10B981","#F59E0B","#8B5CF6","#EC4899","#06B6D4");
 public NebulaService(NebulaRepo repo,ConversationRepo rooms,ConversationMemberRepo members,UsersRepo users,ObjectMapper json,ApplicationEventPublisher events,EntityManager em,MessagesRepo messages){this.messages=messages;this.repo=repo;this.rooms=rooms;this.members=members;this.users=users;this.json=json;this.events=events;this.em=em;}
 private Long number(Object x){if(x==null)return null;try{return Long.valueOf(x.toString());}catch(Exception e){throw new IllegalArgumentException("Mã không hợp lệ.");}}
 private String text(Object x,int max){String s=Objects.toString(x,"").trim();if(s.isEmpty()||s.length()>max)throw new IllegalArgumentException("Nội dung cần từ 1 đến "+max+" ký tự.");return s;}
 @SuppressWarnings("unchecked") private Map<String,Object> data(NebulaResource r){return new LinkedHashMap<>(json.readValue(r.payload,Map.class));}
 private List<Long> ids(Object x){if(!(x instanceof List<?> l))return new ArrayList<>();return new ArrayList<>(l.stream().map(this::number).distinct().toList());}
 private List<Long> roster(Long room){return members.findByConversation_Id(room).stream().map(ConversationMember::getUserId).toList();}
 private void member(Long room,Long user){if(!members.existsByConversation_IdAndUser_Id(room,user))throw new AccessDeniedException("Bạn không thuộc hội thoại này.");}
 private boolean admin(Long room,Long user){return members.existsByConversation_IdAndUser_IdAndRole(room,user,MemberRole.ADMIN);}
 private void group(Long room){if(rooms.findById(room).orElseThrow().getConvoType()!=ConversationType.GROUP)throw new IllegalArgumentException("Chỉ dùng trong nhóm.");}
 private Long leader(Long room){return members.findByConversation_Id(room).stream().filter(m->m.getRole()==MemberRole.ADMIN).map(ConversationMember::getUserId).min(Long::compare).orElseGet(()->roster(room).stream().findFirst().orElseThrow());}
 private boolean communityLeader(Long room,Long user){Object id=repo.findById("meta-"+room).map(this::data).orElseGet(LinkedHashMap::new).get("leaderId");return user.equals(id==null?leader(room):number(id));}
 private void manager(NebulaResource r,Long user){if(!r.ownerId.equals(user)&&!admin(r.roomId,user))throw new AccessDeniedException("Chỉ người tạo hoặc quản trị viên được thao tác.");}
 private Set<Long> linked(NebulaResource r,Map<String,Object>d){Set<Long> all=new LinkedHashSet<>(ids(d.get("rooms")));all.add(r.roomId);return all;}
 private void access(NebulaResource r,Map<String,Object>d,Long user){if(linked(r,d).stream().noneMatch(room->members.existsByConversation_IdAndUser_Id(room,user)))throw new AccessDeniedException("Không được truy cập thẻ này.");}
 private void save(NebulaResource r,Map<String,Object>d){r.payload=json.writeValueAsString(d);repo.save(r);Set<Long> targets=new HashSet<>();for(Long room:linked(r,d))targets.addAll(roster(room));for(Long target:targets)events.publishEvent(new ContactEvent(Map.of("kind","nebula","targetId",target,"resourceId",r.id)));}
 private void deadline(Map<String,Object>d){Object value=d.get("deadline");if(value!=null&&!value.toString().isBlank())try{Instant.parse(value.toString());}catch(Exception e){throw new IllegalArgumentException("Hạn chót không hợp lệ.");}}
 private Map<String,Object> view(NebulaResource r,Long user){Map<String,Object>d=data(r);Map<String,Object> out=new LinkedHashMap<>(d);out.put("id",r.id);out.put("type",r.type);out.put("roomId",r.roomId);out.put("ownerId",r.ownerId);if(r.type.equals("meta")&&d.containsKey("parentId")){out.put("memberIds",roster(r.roomId));out.put("leaderId",leader(r.roomId));}if(r.type.equals("poll")&&Boolean.TRUE.equals(d.get("anonymous"))){Map<String,Object> votes=map(d,"votes");Map<String,Integer> counts=new HashMap<>();for(Object value:votes.values())for(Long id:ids(value))counts.merge(id.toString(),1,Integer::sum);out.remove("votes");out.put("counts",counts);out.put("myVotes",votes.getOrDefault(user.toString(),List.of()));out.put("voterCount",votes.values().stream().filter(v->!ids(v).isEmpty()).count());}return out;}
 @SuppressWarnings("unchecked") private Map<String,Object> map(Map<String,Object>d,String key){Map<String,Object> m=new LinkedHashMap<>((Map<String,Object>)d.getOrDefault(key,Map.of()));d.put(key,m);return m;}
 @SuppressWarnings("unchecked") private List<Map<String,Object>> rows(Map<String,Object>d,String key){List<Map<String,Object>> list=new ArrayList<>((List<Map<String,Object>>)d.getOrDefault(key,List.of()));d.put(key,list);return list;}
 public List<Map<String,Object>> list(Long user){List<Map<String,Object>> result=new ArrayList<>();for(NebulaResource r:repo.findAll()){Map<String,Object>d=data(r);if(linked(r,d).stream().anyMatch(room->members.existsByConversation_IdAndUser_Id(room,user)))result.add(view(r,user));}return result;}
 private NebulaResource meta(Long room){return repo.findById("meta-"+room).orElseGet(()->{NebulaResource r=new NebulaResource();r.id="meta-"+room;r.type="meta";r.roomId=room;r.ownerId=leader(room);r.payload="{}";return r;});}
 private void link(Long room,Long child,String color){if(room.equals(child))throw new IllegalArgumentException("Không thể gắn nhóm vào chính nó.");group(room);group(child);NebulaResource parent=meta(room),sub=meta(child);Map<String,Object> p=data(parent),s=data(sub);if(p.containsKey("parentId")||s.containsKey("parentId")||Boolean.TRUE.equals(s.get("community")))throw new IllegalArgumentException("Nhóm đã thuộc cộng đồng hoặc tạo thành vòng lặp.");p.put("community",true);p.putIfAbsent("leaderId",leader(room));s.put("title",rooms.findById(child).orElseThrow().getTitle());s.put("parentId",room);s.put("rooms",List.of(room,child));s.put("memberIds",roster(child));s.put("color",color);s.put("leaderId",leader(child));List<Long> children=ids(p.get("children"));children.add(child);p.put("children",children);for(Long uid:roster(child))if(!roster(room).contains(uid))members.save(new ConversationMember(rooms.findById(room).orElseThrow(),users.findById(uid).orElseThrow(),MemberRole.MEMBER));members.flush();save(parent,p);save(sub,s);}
 private Long subgroup(Long room,Long creator,String title,List<Long> selected,String color){if(!COLORS.contains(color))throw new IllegalArgumentException("Màu nhóm không hợp lệ.");Set<Long> ids=new LinkedHashSet<>(selected);ids.add(creator);if(ids.size()<3||!roster(room).containsAll(ids))throw new IllegalArgumentException("Chọn ít nhất 3 thành viên thuộc nhóm gốc.");Conversation c=new Conversation(ConversationType.GROUP);c.setTitle(text(title,20));rooms.save(c);for(Long id:ids)members.save(new ConversationMember(c,users.findById(id).orElseThrow(),id.equals(creator)?MemberRole.ADMIN:MemberRole.MEMBER));members.flush();link(room,c.getConversationId(),color);return c.getConversationId();}
 private Long announce(Long room,Long user,String content) {
  Message message=messages.save(new Message(rooms.findById(room).orElseThrow(),users.findById(user).orElseThrow(),content,MessageType.TEXT));
  events.publishEvent(new com.chatApp.cloudChat.event.NebulaMessageEvent(room,com.chatApp.cloudChat.DTO.MessageResponse.from(message)));
  return message.getMessageId();
 }
 public Map<String,Object> create(Long user,Map<String,Object>b){Long room=number(b.get("roomId"));member(room,user);String type=text(b.get("type"),20);em.find(Conversation.class,room,LockModeType.PESSIMISTIC_WRITE);
  if(type.equals("meta")){NebulaResource r=meta(room);Map<String,Object>d=data(r);if(b.containsKey("title")){group(room);String title=text(b.get("title"),20);rooms.findById(room).orElseThrow().setTitle(title);d.put("title",title);}if(b.containsKey("nicknameUserId")){Long id=number(b.get("nicknameUserId"));member(room,id);Map<String,Object> names=map(d,"nicknames");String name=Objects.toString(b.get("nickname"),"").trim();if(name.length()>50)throw new IllegalArgumentException("Biệt danh tối đa 50 ký tự.");if(name.isEmpty())names.remove(id.toString());else names.put(id.toString(),name);}save(r,d);announce(room,user,"[META_UPDATE]"+r.id);return view(r,user);}
  if(type.equals("subgroup")){group(room);if(!communityLeader(room,user))throw new AccessDeniedException("Chỉ Trưởng cộng đồng được tạo nhóm con trực tiếp.");Long child=subgroup(room,user,text(b.get("title"),20),ids(b.get("memberIds")),text(b.get("color"),7));announce(room,user,"[META_UPDATE]meta-"+room);return view(meta(child),user);}
  if(type.equals("merge")&&communityLeader(room,user)){Long child=number(b.get("childId"));member(child,user);link(room,child,text(b.get("color"),7));announce(room,user,"[META_UPDATE]meta-"+room);return view(meta(room),user);}
  if(!Set.of("task","poll","checkin","recruit","merge").contains(type))throw new IllegalArgumentException("Loại thẻ không hợp lệ.");NebulaResource r=new NebulaResource();r.id=UUID.randomUUID().toString();r.type=type;r.roomId=room;r.ownerId=user;Map<String,Object>d=new LinkedHashMap<>();d.put("title",text(b.get("title"),160));d.put("createdAt",Instant.now().toString());d.put("rooms",List.of(room));
  if(type.equals("task")){d.put("description",Objects.toString(b.get("description"),"").substring(0,Math.min(1000,Objects.toString(b.get("description"),"").length())));d.put("priority",Set.of("high","medium","low").contains(b.get("priority"))?b.get("priority"):"medium");d.put("deadline",b.get("deadline"));deadline(d);Long assignee=number(b.get("assigneeId"));if(assignee!=null)member(room,assignee);d.put("assigneeId",assignee);Long subgroup=number(b.get("subgroupId"));if(subgroup!=null){if(!Objects.equals(number(data(meta(subgroup)).get("parentId")),room))throw new IllegalArgumentException("Nhóm phụ trách không thuộc cộng đồng.");d.put("subgroupId",subgroup);}d.put("steps",new ArrayList<>());}
  if(type.equals("poll")){group(room);List<Map<String,Object>> options=new ArrayList<>();Object raw=b.get("options");if(!(raw instanceof List<?> inputs)||inputs.size()<2||inputs.size()>20)throw new IllegalArgumentException("Bình chọn cần 2–20 lựa chọn.");for(int i=0;i<inputs.size();i++)options.add(new LinkedHashMap<>(Map.of("id",i+1,"text",text(inputs.get(i),100))));d.put("options",options);d.put("multiple",Boolean.TRUE.equals(b.get("multiple")));d.put("allowOptions",Boolean.TRUE.equals(b.get("allowOptions")));d.put("anonymous",Boolean.TRUE.equals(b.get("anonymous")));boolean collective="collective".equals(b.get("mode"));if(collective&&ids(data(meta(room)).get("children")).isEmpty())throw new IllegalArgumentException("Cần có nhóm con để bình chọn tập thể.");d.put("mode",collective?"collective":"individual");d.put("votes",new LinkedHashMap<>());}
  if(type.equals("checkin")){group(room);d.put("deadline",text(b.get("deadline"),50));deadline(d);if(!Instant.parse(d.get("deadline").toString()).isAfter(Instant.now()))throw new IllegalArgumentException("Giờ kết thúc phải ở tương lai.");d.put("expected",roster(room));d.put("attendance",new LinkedHashMap<>());}
  if(type.equals("recruit")||type.equals("merge")){text(b.get("title"),20);group(room);String color=text(b.get("color"),7);if(!COLORS.contains(color))throw new IllegalArgumentException("Màu không hợp lệ.");d.put("color",color);d.put("status","open");if(type.equals("recruit")){long max=number(b.get("maxMembers"));if(max<3||max>50)throw new IllegalArgumentException("Số thành viên tối đa từ 3 đến 50.");d.put("maxMembers",max);d.put("applicants",List.of(user));d.put("approved",List.of(user));}else {Long child=number(b.get("childId"));member(child,user);group(child);d.put("childId",child);}}
  save(r,d);String tag=switch(type){case "task"->"TASK_V1";case "poll"->"POLL_V1";case "checkin"->"CHECKIN_V1";case "recruit"->"SUBGROUP_REQ_V1";default->"SUBGROUP_MERGE_REQ";};announce(room,user,"["+tag+"]"+r.id);return view(r,user);
 }
 public Map<String,Object> update(Long user,String id,Map<String,Object>b){NebulaResource r=repo.locked(id).orElseThrow();Map<String,Object>d=data(r);access(r,d,user);String action=text(b.get("action"),30);Long forwardedMessageId=null;
  if(action.equals("forward")){if(!r.type.equals("task"))throw new IllegalArgumentException("Chỉ chuyển tiếp công việc.");Long room=number(b.get("targetId"));member(room,user);Set<Long> copy=linked(r,d);copy.add(room);d.put("rooms",new ArrayList<>(copy));String source=rooms.findById(r.roomId).orElseThrow().getTitle();if(source==null)source="Hội thoại #"+r.roomId;forwardedMessageId=announce(room,user,"[TASK_FORWARD_V1]"+r.id+"|"+java.net.URLEncoder.encode(source,java.nio.charset.StandardCharsets.UTF_8).replace("+","%20"));}
  else if(r.type.equals("task")){List<Map<String,Object>> steps=rows(d,"steps");if(action.equals("addStep")){Long sub=number(d.get("subgroupId"));if(!r.ownerId.equals(user)&&!admin(r.roomId,user)&&(sub==null||!admin(sub,user)))throw new AccessDeniedException("Chỉ người tạo hoặc trưởng nhóm được chia việc.");Long assignee=number(b.get("assigneeId"));if(assignee==null)throw new IllegalArgumentException("Chọn người phụ trách.");member(sub==null?r.roomId:sub,assignee);Map<String,Object>s=new LinkedHashMap<>();s.put("id",UUID.randomUUID().toString());s.put("title",text(b.get("title"),160));s.put("assigneeId",assignee);s.put("deadline",b.get("deadline"));deadline(s);if(s.get("deadline")!=null&&d.get("deadline")!=null&&Instant.parse(s.get("deadline").toString()).isAfter(Instant.parse(d.get("deadline").toString())))throw new IllegalArgumentException("Hạn việc con không được muộn hơn việc tổng.");s.put("done",false);steps.add(s);}else if(action.equals("toggleStep")){Map<String,Object>s=steps.stream().filter(x->Objects.equals(x.get("id"),b.get("stepId"))).findFirst().orElseThrow();if(!user.equals(number(s.get("assigneeId")))&&!user.equals(r.ownerId)&&!admin(r.roomId,user))throw new AccessDeniedException("Chỉ người phụ trách được hoàn thành đầu việc.");s.put("done",Boolean.TRUE.equals(b.get("done")));}else if(action.equals("complete")){if(!user.equals(number(d.get("assigneeId"))))manager(r,user);d.put("done",Boolean.TRUE.equals(b.get("done")));}else throw new IllegalArgumentException("Thao tác không hợp lệ.");d.put("steps",steps);}
  else if(r.type.equals("poll")){member(r.roomId,user);if(action.equals("addOption")){if(!Boolean.TRUE.equals(d.get("allowOptions")))throw new AccessDeniedException("Không cho phép thêm phương án.");List<Map<String,Object>> options=rows(d,"options");if(options.size()>=20)throw new IllegalArgumentException("Tối đa 20 phương án.");options.add(new LinkedHashMap<>(Map.of("id",options.size()+1,"text",text(b.get("text"),100))));}else if(action.equals("vote")){List<Long> choices=ids(b.get("choices"));List<Map<String,Object>> options=rows(d,"options");if((!Boolean.TRUE.equals(d.get("multiple"))&&choices.size()>1)||!options.stream().map(o->number(o.get("id"))).toList().containsAll(choices))throw new IllegalArgumentException("Phiếu không hợp lệ.");String key=user.toString();if("collective".equals(d.get("mode"))){Long sub=number(b.get("subgroupId"));if(sub==null||!ids(data(meta(r.roomId)).get("children")).contains(sub)||!admin(sub,user))throw new AccessDeniedException("Chỉ trưởng nhóm con được chốt phiếu đại diện.");key="group-"+sub;}map(d,"votes").put(key,choices);}else throw new IllegalArgumentException("Thao tác không hợp lệ.");}
  else if(r.type.equals("checkin")){member(r.roomId,user);if(!action.equals("checkin")||!Instant.now().isBefore(Instant.parse(d.get("deadline").toString())))throw new IllegalArgumentException("Đã đóng điểm danh.");if(!ids(d.get("expected")).contains(user))throw new AccessDeniedException("Bạn không thuộc danh sách điểm danh.");map(d,"attendance").putIfAbsent(user.toString(),Instant.now().toString());}
  else if(r.type.equals("recruit")){member(r.roomId,user);List<Long> applicants=ids(d.get("applicants")),approved=ids(d.get("approved"));long max=number(d.get("maxMembers"));if(!"open".equals(d.get("status"))||approved.size()>=max)throw new IllegalArgumentException("Đã đủ số lượng.");if(action.equals("join")){if(!applicants.contains(user))applicants.add(user);}else if(action.equals("approve")){if(!r.ownerId.equals(user)&&!communityLeader(r.roomId,user))throw new AccessDeniedException("Chỉ người đề xuất hoặc Trưởng cộng đồng được duyệt.");Long target=number(b.get("userId"));member(r.roomId,target);if(!applicants.contains(target))throw new IllegalArgumentException("Chưa đăng ký.");if(!approved.contains(target))approved.add(target);if(approved.size()==max){em.find(Conversation.class,r.roomId,LockModeType.PESSIMISTIC_WRITE);Long child=subgroup(r.roomId,r.ownerId,d.get("title").toString(),approved,d.get("color").toString());d.put("childId",child);d.put("status","active");}}else throw new IllegalArgumentException("Thao tác không hợp lệ.");d.put("applicants",applicants);d.put("approved",approved);}
  else if(r.type.equals("merge")){if(!action.equals("approve")||!communityLeader(r.roomId,user))throw new AccessDeniedException("Chỉ trưởng cộng đồng được duyệt sáp nhập.");em.find(Conversation.class,r.roomId,LockModeType.PESSIMISTIC_WRITE);if(!"open".equals(d.get("status")))throw new IllegalArgumentException("Đã duyệt yêu cầu.");link(r.roomId,number(d.get("childId")),d.get("color").toString());d.put("status","active");}
  else throw new IllegalArgumentException("Thao tác không hợp lệ.");save(r,d);Map<String,Object> result=view(r,user);if(forwardedMessageId!=null)result.put("forwardMessageId",forwardedMessageId);return result;
 }
}
